  /// Between 0 and 1.
  ///
  /// Defaults to `0.5`.
  Expression<num> get exaggeration =>
      _property('hillshade-exaggeration', decodeNum, const Literal(0.5));

  set exaggeration(Expression<num>? value) =>
      _setExpression('hillshade-exaggeration', value);

  /// How [exaggeration] changes to a new value.
