  @override
  String get type => 'line';

  @override
  Set<String> get _layoutProperties => const {
    'line-cap',
    'line-join',
    'line-miter-limit',
    'line-round-limit',
    'line-sort-key',
    'visibility',
  };

  /// The display of line endings.
  ///
  /// Defaults to `"butt"`.
  Expression<LineCap> get cap => _property(
    'line-cap',
    decodeEnum(LineCap.values),
    const Literal(LineCap.butt),
  );

  set cap(Expression<LineCap>? value) => _setExpression('line-cap', value);

  /// The display of lines when joining.
  ///
  /// Defaults to `"miter"`.
  Expression<LineJoin> get join => _property(
    'line-join',
    decodeEnum(LineJoin.values),
    const Literal(LineJoin.miter),
  );

  set join(Expression<LineJoin>? value) => _setExpression('line-join', value);

  /// Used to automatically convert miter joins to bevel joins for sharp angles.
  ///
  /// Defaults to `2`.
  Expression<num> get miterLimit =>
      _property('line-miter-limit', decodeNum, const Literal(2));

  set miterLimit(Expression<num>? value) =>
      _setExpression('line-miter-limit', value);

  /// Used to automatically convert round joins to miter joins for shallow angles.
  ///
  /// Defaults to `1.05`.
  Expression<num> get roundLimit =>
      _property('line-round-limit', decodeNum, const Literal(1.05));

  set roundLimit(Expression<num>? value) =>
      _setExpression('line-round-limit', value);

  /// Sorts features in ascending order based on this value. Features with a
  /// higher sort key will appear above features with a lower sort key.
  Expression<num>? get sortKey => _propertyOrNull('line-sort-key', decodeNum);

  set sortKey(Expression<num>? value) => _setExpression('line-sort-key', value);

  /// The opacity at which the line will be drawn.
  ///
  /// Between 0 and 1.
  ///
  /// Defaults to `1`.
  Expression<num> get opacity =>
      _property('line-opacity', decodeNum, const Literal(1));

  set opacity(Expression<num>? value) => _setExpression('line-opacity', value);

  /// How [opacity] changes to a new value.
  StyleTransition? get opacityTransition => _transition('line-opacity');

  set opacityTransition(StyleTransition? value) =>
      _setTransition('line-opacity', value);

  /// Opacity applied to the layer as a whole. Unlike
  /// [`line-opacity`](https://maplibre.org/maplibre-style-spec/layers/#line-opacity)
  /// and alpha values in
  /// [`line-color`](https://maplibre.org/maplibre-style-spec/layers/#line-color),
  /// which are applied per feature and accumulate where lines overlap,
  /// `line-layer-opacity` is applied once so overlapping lines appear as a single
  /// surface at the given opacity. When both `line-opacity` and
  /// `line-layer-opacity` are set, the per-feature, overlap accumulation is
  /// preserved, then layer-opacity composites the result. This property affects
  /// only the layer it is set on and cannot be used to composite multiple layers
  /// together or control how this layer blends with layers above or below it.
  ///
  /// ![line-opacity vs. line-layer-opacity](assets/line-layer-opacity.svg)
  ///
  /// Between 0 and 1.
  ///
  /// Defaults to `1`.
  Expression<num> get layerOpacity =>
      _property('line-layer-opacity', decodeNum, const Literal(1));

