  /// [`line-opacity`](https://maplibre.org/maplibre-style-spec/expressions/#line-opacity),
  /// this property affects the final composited layer output and determines how
  /// it interacts with the existing map contents.
  ///
  /// ![line-layer-blend examples](assets/line-layer-blend.svg)
  ///
  /// Defaults to `"normal"`.
  ///
  /// Takes no expressions, only literals.
  Expression<LineLayerBlend> get layerBlend => _property(
    'line-layer-blend',
    decodeEnum(LineLayerBlend.values),
    const Literal(LineLayerBlend.normal),
  );

  set layerBlend(Expression<LineLayerBlend>? value) =>
      _setExpression('line-layer-blend', value);

  /// The color with which the line will be drawn.
  ///
  /// Defaults to `"#000000"`.
  Expression<Color> get color =>
      _property('line-color', decodeColor, const Literal(Color(0xFF000000)));

  set color(Expression<Color>? value) => _setExpression('line-color', value);

  /// How [color] changes to a new value.
  StyleTransition? get colorTransition => _transition('line-color');

  set colorTransition(StyleTransition? value) =>
      _setTransition('line-color', value);

  /// The geometry's offset. Values are `[x, y]` where negatives indicate left and
  /// up, respectively.
  ///
  /// In pixels.
