/// [`symbol-sort-key`](https://maplibre.org/maplibre-style-spec/layers/#symbol-sort-key).
///
/// {@category Style}
/// {@subCategory Style Layers}
enum SymbolZOrder implements StyleEnum {
  /// Sorts symbols by
