  /// If the icon collides with another previously drawn symbol, the overlap mode
  /// for that symbol is checked. If the previous symbol was placed using `never`
  /// overlap mode, the new icon is hidden. If the previous symbol was placed
  /// using `always` or `cooperative` overlap mode, the new icon is visible.
  cooperative('cooperative');

  const IconOverlap(this.value);

