///
/// {@category Style}
/// {@subCategory Style Layers}
enum IconTranslateAnchor implements StyleEnum {
  /// Icons are translated relative to the map.
  map('map'),

  /// Icons are translated relative to the viewport.
  viewport('viewport');

  const IconTranslateAnchor(this.value);

  @override
  final String value;
}

/// Controls the frame of reference for
/// [`text-translate`](https://maplibre.org/maplibre-style-spec/layers/#text-translate).
///
/// {@category Style}
/// {@subCategory Style Layers}
enum TextTranslateAnchor implements StyleEnum {
  /// The text is translated relative to the map.
  map('map'),

  /// The text is translated relative to the viewport.
  viewport('viewport');

  const TextTranslateAnchor(this.value);

  @override
  final String value;
}
